/**
 * Empirical horario planning coefficients from public WCA WCIFs.
 * Constants live in `horario-estimates-data.ts` (regenerated by analyze:horario).
 * Durations are scheduled slots, not measured floor time.
 */

import { mexicoRegionById } from "./data/mexico";
import { HORARIO_ESTIMATES_DATA } from "./horario-estimates-data";
import { HORARIO_REGIONAL_MIN_SAMPLE } from "./wcif/flatten-rounds";

export type HorarioEventEstimateConstants = {
  sampleSize: number;
  medianMinutesPerGroup: number;
  medianMinutesPerCompetitor: number;
  medianCompetitorsPerGroup: number;
};

export type HorarioEstimatesData = {
  national: Record<string, HorarioEventEstimateConstants>;
  byRegion: Record<string, Record<string, HorarioEventEstimateConstants>>;
  meta: {
    generatedAt: string;
    competitionCount: number;
    roundCount: number;
  };
};

export type HorarioEstimateSource = "region" | "national";

export type HorarioEstimateLookup = {
  estimate: HorarioEventEstimateConstants;
  source: HorarioEstimateSource;
  regionId: string | null;
  regionLabel: string | null;
};

export { HORARIO_ESTIMATES_DATA };

export function getHorarioEventEstimate(
  eventId: string,
  options?: { regionId?: string | null },
): HorarioEstimateLookup | null {
  const regionId = options?.regionId ?? null;
  if (regionId) {
    const regional = HORARIO_ESTIMATES_DATA.byRegion[regionId]?.[eventId];
    if (regional && regional.sampleSize >= HORARIO_REGIONAL_MIN_SAMPLE) {
      return {
        estimate: regional,
        source: "region",
        regionId,
        regionLabel: mexicoRegionById(regionId)?.displayName ?? regionId,
      };
    }
  }

  const national = HORARIO_ESTIMATES_DATA.national[eventId];
  if (!national) return null;
  return {
    estimate: national,
    source: "national",
    regionId: null,
    regionLabel: null,
  };
}

/** Round estimated minutes up to the next 5-minute block (min 5). */
export function roundUpScheduleMinutes(minutes: number): number {
  if (!Number.isFinite(minutes) || minutes <= 0) return 5;
  return Math.max(5, Math.ceil(minutes / 5) * 5);
}

export function estimateRoundDurationMinutes(input: {
  eventId: string;
  competitors: number;
  groups: number | null;
  regionId?: string | null;
}): number | null {
  const lookup = getHorarioEventEstimate(input.eventId, {
    regionId: input.regionId,
  });
  if (!lookup) return null;
  const { estimate } = lookup;
  if (input.groups != null && input.groups > 0) {
    return roundUpScheduleMinutes(
      input.groups * estimate.medianMinutesPerGroup,
    );
  }
  if (input.competitors > 0) {
    return roundUpScheduleMinutes(
      input.competitors * estimate.medianMinutesPerCompetitor,
    );
  }
  return null;
}

/** Label for UI helper text: regional display name or “México”. */
export function horarioEstimateCorpusLabel(
  regionId: string | null | undefined,
): string {
  if (!regionId) return "México";
  const regional = HORARIO_ESTIMATES_DATA.byRegion[regionId];
  const hasRegionalCell = regional
    ? Object.values(regional).some(
        (item) => item.sampleSize >= HORARIO_REGIONAL_MIN_SAMPLE,
      )
    : false;
  if (!hasRegionalCell) return "México";
  return mexicoRegionById(regionId)?.displayName ?? regionId;
}
